CREATE TABLE media_technical_metadata (media_file_id VARCHAR(36) PRIMARY KEY, file_size BIGINT NOT NULL, modified_at VARCHAR(40) NOT NULL, container VARCHAR(64), duration_ms BIGINT, overall_bitrate BIGINT, video_codec VARCHAR(64), video_profile VARCHAR(64), width INT, height INT, frame_rate DOUBLE, video_bitrate BIGINT, bit_depth INT, hdr_type VARCHAR(32), audio_codec VARCHAR(64), audio_channels INT, audio_sample_rate INT, audio_bitrate BIGINT, audio_language VARCHAR(32), audio_tracks JSON NOT NULL, subtitle_tracks JSON NOT NULL, analyzed_at VARCHAR(40) NOT NULL, FOREIGN KEY(media_file_id) REFERENCES media_files(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE playback_sessions (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, media_item_id VARCHAR(36) NOT NULL, media_file_id VARCHAR(36) NOT NULL, episode_id VARCHAR(36), mode VARCHAR(32) NOT NULL, quality_profile VARCHAR(32) NOT NULL, reason JSON NOT NULL, stream_token_hash VARCHAR(64) NOT NULL, started_at VARCHAR(40) NOT NULL, last_activity_at VARCHAR(40) NOT NULL, position_ms BIGINT NOT NULL DEFAULT 0, duration_ms BIGINT NOT NULL DEFAULT 0, client_id VARCHAR(128), client_name VARCHAR(128), ip_address VARCHAR(64), status VARCHAR(32) NOT NULL, pipeline_key VARCHAR(64), bytes_served BIGINT NOT NULL DEFAULT 0, buffer_events BIGINT NOT NULL DEFAULT 0, ended_at VARCHAR(40), INDEX idx_playback_sessions_user(user_id,last_activity_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(media_item_id) REFERENCES media_items(id), FOREIGN KEY(media_file_id) REFERENCES media_files(id), FOREIGN KEY(episode_id) REFERENCES tv_episodes(id)) ENGINE=InnoDB;
CREATE TABLE playback_progress (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, media_item_id VARCHAR(36) NOT NULL, episode_id VARCHAR(36), content_key VARCHAR(80) NOT NULL, position_ms BIGINT NOT NULL, duration_ms BIGINT NOT NULL, percentage DOUBLE NOT NULL, updated_at VARCHAR(40) NOT NULL, completed_at VARCHAR(40), UNIQUE KEY uq_progress_user_content(user_id,content_key), INDEX idx_playback_progress_user(user_id,updated_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE, FOREIGN KEY(episode_id) REFERENCES tv_episodes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE playback_history (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, media_item_id VARCHAR(36) NOT NULL, episode_id VARCHAR(36), content_key VARCHAR(80) NOT NULL, started_at VARCHAR(40) NOT NULL, last_watched_at VARCHAR(40) NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE, watch_time_ms BIGINT NOT NULL DEFAULT 0, session_count BIGINT NOT NULL DEFAULT 1, UNIQUE KEY uq_history_user_content(user_id,content_key), INDEX idx_playback_history_user(user_id,last_watched_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(media_item_id) REFERENCES media_items(id) ON DELETE CASCADE, FOREIGN KEY(episode_id) REFERENCES tv_episodes(id) ON DELETE CASCADE) ENGINE=InnoDB;
